From f234675becbce09d769b9ad331d80d27bdb815a6 Mon Sep 17 00:00:00 2001
From: Tobias Ellinghaus <me@houz.org>
Date: Tue, 15 Aug 2017 15:51:08 +0200
Subject: [PATCH] Fix broken legacy_params in some imageio formats

This fixes a bug introduced in 5f13d2527398eb82591fea828bbee7f13f1cc8f7
which most likely broke people's old export presets. Given how old it is
and the lack of complaints it's probably only a minor issue though. :-)

diff --git a/src/imageio/format/j2k.c b/src/imageio/format/j2k.c
index 515d9b1240..6c80be0d26 100644
--- a/src/imageio/format/j2k.c
+++ b/src/imageio/format/j2k.c
@@ -531,7 +531,6 @@ void *legacy_params(dt_imageio_module_format_t *self, const void *const old_para
       int max_width, max_height;
       int width, height;
       char style[128];
-      gboolean style_append;
       int bpp;
       dt_imageio_j2k_format_t format;
       dt_imageio_j2k_preset_t preset;

diff --git a/src/imageio/format/tiff.c b/src/imageio/format/tiff.c
index 76390c0c62..697115ab0e 100644
--- a/src/imageio/format/tiff.c
+++ b/src/imageio/format/tiff.c
@@ -269,7 +269,6 @@ void *legacy_params(dt_imageio_module_format_t *self, const void *const old_para
       int max_width, max_height;
       int width, height;
       char style[128];
-      gboolean style_append;
       int bpp;
       int compress;
       TIFF *handle;
@@ -292,6 +291,7 @@ void *legacy_params(dt_imageio_module_format_t *self, const void *const old_para
   }
   return NULL;
 }
+
 void *get_params(dt_imageio_module_format_t *self)
 {
   dt_imageio_tiff_t *d = (dt_imageio_tiff_t *)calloc(1, sizeof(dt_imageio_tiff_t));

diff --git a/src/imageio/format/webp.c b/src/imageio/format/webp.c
index b95d39270f..442b8fbacc 100644
--- a/src/imageio/format/webp.c
+++ b/src/imageio/format/webp.c
@@ -191,7 +191,6 @@ void *legacy_params(dt_imageio_module_format_t *self, const void *const old_para
       int max_width, max_height;
       int width, height;
       char style[128];
-      gboolean style_append;
       int comp_type;
       int quality;
       int hint;
@@ -214,6 +213,7 @@ void *legacy_params(dt_imageio_module_format_t *self, const void *const old_para
   }
   return NULL;
 }
+
 void *get_params(dt_imageio_module_format_t *self)
 {
   dt_imageio_webp_t *d = (dt_imageio_webp_t *)calloc(1, sizeof(dt_imageio_webp_t));
